import * as THREE from 'three';
// Geometric coverage only, no hardware fragment-invocation claim.
export function groundCoverage(w){
 const r=w.renderer,size=r.getDrawingBufferSize(new THREE.Vector2()),target=new THREE.WebGLRenderTarget(size.x,size.y,{depthBuffer:false}),scene=new THREE.Scene(),materials=[];
 const saved=r.getRenderTarget(),clear=r.getClearColor(new THREE.Color()),alpha=r.getClearAlpha(),auto=r.autoClear;
 w.scene.updateMatrixWorld(true);w.camera.updateMatrixWorld(true);let groundMeshes=0,mudMeshes=0;
 w.scene.traverseVisible(o=>{const ground=!!o.userData.ground,mud=!!o.userData.globalMudBlend;if(!ground&&!mud)return;if(!o.layers.test(w.camera.layers))return;
 const material=new THREE.RawShaderMaterial({vertexShader:'precision highp float;attribute vec3 position;uniform mat4 projectionMatrix,modelViewMatrix;void main(){gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'precision highp float;uniform vec3 tally;void main(){gl_FragColor=vec4(tally,1.);}',uniforms:{tally:{value:new THREE.Vector3(ground?1/255:0,mud?1/255:0,0)}},side:o.material.side,depthTest:false,depthWrite:false,transparent:true,blending:THREE.CustomBlending,blendEquation:THREE.AddEquation,blendSrc:THREE.OneFactor,blendDst:THREE.OneFactor,toneMapped:false});materials.push(material);const mesh=new THREE.Mesh(o.geometry,material);mesh.matrixAutoUpdate=false;mesh.matrix.copy(o.matrixWorld);scene.add(mesh);groundMeshes+=Number(ground);mudMeshes+=Number(mud);});
 try{r.autoClear=true;r.setClearColor(0,0);r.setRenderTarget(target);r.render(scene,w.camera);const pixels=new Uint8Array(size.x*size.y*4);r.readRenderTargetPixels(target,0,0,size.x,size.y,pixels);let groundPixels=0,mudPixels=0,overlap=0,groundFragments=0,mudFragments=0,maxGround=0,maxMud=0;for(let i=0;i<pixels.length;i+=4){const g=pixels[i],m=pixels[i+1];groundPixels+=Number(g>0);mudPixels+=Number(m>0);overlap+=Number(g>0&&m>0);groundFragments+=g;mudFragments+=m;maxGround=Math.max(maxGround,g);maxMud=Math.max(maxMud,m);}return {width:size.x,height:size.y,groundMeshes,mudMeshes,groundPixels,mudPixels,overlap,groundFragments,mudFragments,maxGround,maxMud,scope:'Projected geometric coverage without depth rejection or other-scene occlusion; RGBA8 additive counts saturate at255. Not actual shader invocations.'};}
 finally{r.setRenderTarget(saved);r.setClearColor(clear,alpha);r.autoClear=auto;materials.forEach(m=>m.dispose());target.dispose();}
}
